"use strict";(globalThis.webpackChunkassamese_app=globalThis.webpackChunkassamese_app||[]).push([[532],{532(e){e.exports=JSON.parse('{"title":"Lektion 9 \u2013 Substantiv Klassifikator ","introduction":[{"erkl\xe4rung":"Im Assamesischen m\xfcssen Nomen beim Z\xe4hlen immer mit einem Klassifikator verbunden werden \u2013 \xe4hnlich wie im Deutschen \'ein Blatt Papier\' oder \'ein St\xfcck Kuchen\', nur ist es dort grammatisch verpflichtend: Man kann nicht einfach \'drei Buch\' sagen, sondern braucht die richtige Form wie \'tini-khon kitap\' (drei-CLF Buch)."},{"erkl\xe4rung":"eder Klassifikator kategorisiert Nomen nach Form, Belebtheit oder sozialem Status \u2013 so steht -zon f\xfcr m\xe4nnliche Personen, -dal f\xfcr lange stabf\xf6rmige Dinge und -khon f\xfcr flache Objekte; dazu kommen Honorativformen wie -goraki, die Respekt gegen\xfcber der genannten Person ausdr\xfccken."},{"erkl\xe4rung":"Obwohl Assamesisch eine indoarische Sprache ist, besitzt es dieses reiche Klassifikatorsystem vor allem durch Sprachkontakt mit benachbarten tibeto-burmanischen Sprachen wie Bodo und Garo \u2013 ein Beispiel f\xfcr areale Diffusion, bei der grammatische Strukturen \xfcber Sprachgrenzen hinweg \xfcbernommen werden, unabh\xe4ngig von der genetischen Verwandtschaft."},{"erkl\xe4rung":"Welche Klassifikator mit welchem Substantiv kommt ist schwer zu erkl\xe4ren. Es ist bisschen wie der, die , das in Deutsch. Es gibt ungef\xe4hr Regeln, aber die greifen nicht immer zu."}],"vocab":[{"deutsch":"Klassifikator f\xfcr M\xe4nner / Personen (neutral/formell)","assamese":"-\u099c\u09a8 (-zon)","link to audio":"/audio/classifiers/zon.m4a"},{"deutsch":"Klassifikator f\xfcr Frauen","assamese":"-\u099c\u09a8\u09c0 (-zoni)","link to audio":"/audio/classifiers/zoni.m4a"},{"deutsch":"Klassifikator f\xfcr flache / blattartige Objekte (B\xfccher, Matten, Zimmer, Land)","assamese":"-\u0996\u09a8 (-khon)","link to audio":"/audio/classifiers/khon.m4a"},{"deutsch":"Klassifikator f\xfcr allgemeine unbelebte Objekte (neutral/Standard)","assamese":"-\u099f\u09cb (-tu)","link to audio":"/audio/classifiers/to.m4a"},{"deutsch":"Klassifikator f\xfcr lange, stabf\xf6rmige Objekte (St\xf6cke, Seile, Fl\xfcsse, Stra\xdfen)","assamese":"-\u09a1\u09be\u09b2 (-dal)","link to audio":"/audio/classifiers/dal.m4a"},{"deutsch":"Klassifikator f\xfcr d\xfcnne, blattf\xf6rmige Objekte (Bl\xe4tter, Papierb\xf6gen)","assamese":"-\u09aa\u09be\u09a4 (-pat)","link to audio":"/audio/classifiers/pat.m4a"},{"deutsch":"Klassifikator f\xfcr gebundene Objekte","assamese":"-\u0995\u09bf\u09a4\u09be (-kita)","link to audio":"/audio/classifiers/kita.m4a"},{"deutsch":"Pluralmarker f\xfcr Personen / Dinge (allgemein)","assamese":"-\u09ac\u09cb\u09f0 (-b\xfcr)","link to audio":"/audio/classifiers/bor.m4a"},{"deutsch":"Pluralmarker (betont, definit)","assamese":"-\u09ac\u09bf\u09b2\u09be\u0995 (-bilak)","link to audio":"/audio/classifiers/bilak.m4a"},{"deutsch":"Kollektivmarker f\xfcr Gruppen (z.B. eine Herde, eine Schar)","assamese":"-\u099c\u09be\u0995 (-zak)","link to audio":"/audio/classifiers/zak.m4a"},{"deutsch":"Kollektivmarker f\xfcr Fl\xfcssigkeiten / Massennomen (z.B. die Milch, das Wasser)","assamese":"-\u0996\u09bf\u09a8\u09bf (-khini)","link to audio":"/audio/classifiers/khini.m4a"}],"examples":[{"assamese":"Mur kitap khon bhari hoi","deutsch":"Mein Buch ist schwer","wort f\xfcr wort":"Mein Buch schwer ist","link":"/audio/g9/Example_g_1.m4a"},{"assamese":"Manuh jon aji ahibo ","deutsch":"Der man wird heute kommen","wort f\xfcr wort":"Man der heute kommen (wird)","link":"/audio/g9/Example_g_2.m4a"},{"assamese":"Sorai bur uri goise","deutsch":"Die Vogel fleigen weg","wort f\xfcr wort":"Vogel die fliegen (weg)gehen","link":"/audio/g9/Example_g_3.m4a"},{"assamese":"Alohi bilak ahise","deutsch":"Die Gaaste sind gekommen ","wort f\xfcr wort":"Gaaste die kommen (sind gerade gekommen)","link":"/audio/g9/Example_g_4.m4a"},{"assamese":"Eta Goru zak ahise","deutsch":"Eine Gruppe von Kuhe kommt","wort f\xfcr wort":"Eine Gruppe von Kuhe kommt","link":"/audio/g9/Example_g_5.m4a"},{"assamese":"Bhat kita tan hoise","deutsch":"Die Reis ist hart (eher nicht weiich genug)","wort f\xfcr wort":"Reise deise(menge) hart ist","link":"/audio/g9/Example_g_6.m4a"}]}')}}]);